def targetJavaVersion = 11

tasks.withType(JavaCompile).configureEach {
	options.release = targetJavaVersion
}

tasks.withType(KotlinJvmCompile).configureEach {
	compilerOptions {
		jvmTarget = JvmTarget.fromTarget(targetJavaVersion.toString())
		freeCompilerArgs.addAll(
			'-Xno-call-assertions',
			'-Xno-param-assertions',
			'-Xno-receiver-assertions',
			"-Xjdk-release=$targetJavaVersion",
		)
	}
}

tasks.named('jar', Jar) {
	// We don't need the thin jar, use the fatJar instead.
	enabled = false
}

def fatJarProvider = tasks.register('fatJar', Jar) { task ->
	task.archiveClassifier = 'fat'

	task.manifest {
		attributes 'Main-Class': 'com.jakewharton.gradle.dependencies.DependencyTreeDiff'
	}

	task.from sourceSets.named('main').map { it.output }
	task.from configurations.named('runtimeClasspath').map {
		it.asFileTree.files.collect { it.isDirectory() ? it : zipTree(it) }
	}

	task.exclude '**/*.kotlin_metadata'
	task.exclude '**/*.kotlin_module'
	task.exclude '**/*.kotlin_builtins'
	task.exclude '**/module-info.class'
	task.exclude 'META-INF/maven/**'
}

def r8File = layout.buildDirectory.file("libs/${base.archivesName.get()}-r8.jar").get().asFile
def rulesFile = project.file("src/main/rules.txt")

def r8Jar = tasks.register('r8Jar', JavaExec) { task ->
	def fatJarFile = fatJarProvider.get().archiveFile
	task.inputs.file(fatJarFile)
	task.inputs.file(rulesFile)
	task.outputs.file(r8File)

	// R8 uses the executing JDK to determine the classfile target.
	javaLauncher = javaToolchains.launcherFor {
		languageVersion = JavaLanguageVersion.of(11)
		vendor = JvmVendorSpec.AZUL
	}

	task.classpath(configurations.r8)
	task.mainClass = 'com.android.tools.r8.R8'
	task.args = [
		'--release',
		'--classfile',
		'--output', r8File.path,
		'--pg-conf', rulesFile.path,
		'--lib', System.properties['java.home'].toString(),
		fatJarFile.get().asFile.path
	]
}

def binaryFile = layout.buildDirectory.file("${base.archivesName.get()}.jar").get().asFile
def binaryJar = tasks.register('binaryJar') { task ->
	task.dependsOn(r8Jar)

	task.inputs.file(r8File)
	task.outputs.file(binaryFile)

	task.doLast {
		binaryFile.getParentFile().mkdirs()
		binaryFile.delete()
		binaryFile << "#!/bin/sh\n\nexec java \$JAVA_OPTS -jar \$0 \"\$@\"\n\n"
		r8File.withInputStream { binaryFile.append it }

		binaryFile.setExecutable true, false
	}
}

tasks.named('assemble').configure { task ->
	task.dependsOn(binaryJar)
}

artifacts {
	archives file: binaryFile, name: 'binary', type: 'jar', builtBy: binaryJar, classifier: 'binary'
}

plugins {
	alias(libs.plugins.kotlin.multiplatform)
	alias(libs.plugins.kotlin.serialization)
	alias(libs.plugins.jetbrains.compose)

	// For implicit distribution configuration. See https://youtrack.jetbrains.com/issue/KT-50227.
	id 'application'
}

mainClassName = 'com.jakewharton.posterbox.Main'

tasks.register('gitShaWriterTask') {
	def gitSha = 'git rev-parse --verify HEAD'.execute().text.trim()
	it.inputs.property("gitSha", gitSha)

	def generatedDir = project.layout.buildDirectory.dir("generated/gitSha")
	it.outputs.dir(generatedDir)

	it.doLast {
		def versionFile = generatedDir.get().file("com/jakewharton/posterbox/version.kt").asFile
		versionFile.parentFile.mkdirs()
		versionFile.text = """// Generated file. Do not edit!
package com.jakewharton.posterbox

internal const val gitSha = "${gitSha}"
"""
	}
}

kotlin {
	js("frontend") {
		browser()
		binaries.executable()
	}
	jvm("backend") {
		withJava() // For 'application' plugin. See https://youtrack.jetbrains.com/issue/KT-45038.
	}

	sourceSets {
		commonMain {
			kotlin {
				srcDir(gitShaWriterTask)
			}
			dependencies {
				api(libs.kotlinx.serialization.core)
				implementation(libs.kotlinx.serialization.json)
			}
		}
		commonTest {
			dependencies {
				implementation(libs.kotlin.test)
			}
		}
		backendMain {
			dependencies {
				implementation(libs.kotlinx.coroutines.core)
				implementation(libs.kotlinx.serialization.core)
				implementation(libs.kotlinx.serialization.json)
				implementation(libs.ktor.server.core)
				implementation(libs.ktor.server.cio)
				implementation(libs.ktor.client.java)
				implementation(libs.ktoml)
				implementation(libs.clikt)
				implementation(libs.slf4j.simple)
				// This is only so the compiler plugin (which is added to all targets) does not error.
				implementation(libs.jetbrains.compose.runtime)
			}
		}
		frontendMain {
			dependencies {
				implementation(libs.kotlinx.coroutines.core)
				implementation(libs.ktor.client.js)
				implementation(libs.jetbrains.compose.web.core)
			}
		}
	}
}

if (hasProperty("skipNodeDownload")) {
	kotlinNodeJs {
		download = false
	}
}

// Embed compiled JS and other frontend resources into the backend jar.
def backendJar = tasks.named('backendJar')
backendJar.configure {
	from(tasks.named("frontendBrowserDistribution")) {
		into('static')
	}
}

// Workaround for https://youtrack.jetbrains.com/issue/KT-37964.
distributions {
	main {
		contents {
			from(backendJar) {
				rename('.*', "${project.name}.jar")
				into('lib')
			}
		}
	}
}

// Disable unused distribution format.
tasks.named('distTar').configure {
	enabled = false
}

// The JS build targets the 'build/distributions/' directory so don't stomp on it.
// See also https://youtrack.jetbrains.com/issue/KT-42683.
tasks.named('distZip').configure {
	destinationDirectory.set(layout.buildDirectory.dir('dist'))
}

// Have the unzipped distribution available from 'assemble' for convenience.
tasks.named("assemble").configure { task ->
	task.dependsOn(tasks.getByName("installDist"))
}

